def transform(grid):
    h, w = len(grid), len(grid[0])

    # The left pattern ends at the first all-zero separator column.
    split = next((c for c in range(w) if all(grid[r][c] == 0 for r in range(h))), w)
    out = [row[:split] for row in grid]

    def signature(cells):
        min_r = min(r for r, c in cells)
        min_c = min(c for r, c in cells)
        return frozenset((r - min_r, c - min_c) for r, c in cells)

    # Record the shape associated with each colored object on the right.
    shapes = {}
    for color in range(1, 10):
        cells = {(r, c) for r in range(h) for c in range(split, w)
                 if grid[r][c] == color}
        if cells:
            shapes[signature(cells)] = color

    # Find zero-shaped cavities in the left pattern and fill matching ones.
    seen = set()
    for r in range(h):
        for c in range(split):
            if out[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < split and
                            out[nr][nc] == 0 and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            color = shapes.get(signature(component))
            if color is not None:
                for rr, cc in component:
                    out[rr][cc] = color

    return out
